mapper.select:
select A.SEQ_ID seqId, CASE WHEN B.MATCH_STATUS IS NULL THEN #{TRD_MATCH_STATUS_01} ELSE B.MATCH_STATUS END matchStatus, ROUND(F.MARCH_QTY / A.SHARE_AMT,4) matchProgress, A.TRADE_MARKET tradeMarket, A.APPLY_TRADE_ID applyTradeId, A.SEC_ACCT_ID secAcctId, C.SEC_ACCT_NAME secAcctName, A.SEC_TYPE secType, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_MARKET_ID END finprodMarketId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ID END finprodId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ABBR END finprodAbbr, A.FINPROD_TYPE2 finprodType2, A.SEAT_NUMBER seatNumber, A.TRADE_PLAT tradePlat, A.PS ps, nvl(A.SHARE_AMT,0) - nvl(F.MARCH_QTY,0) remainNum, nvl(A.FPRICE_AMT,0) - nvl(F.MARCH_AMT,0) remainAmount, A.UNIT_FPRICE unitFprice, A.UNIT_CPRICE unitCprice, A.CCY ccy, A.TRADE_DATE dealDate, A.TRADE_DATE tradeDate, A.SETTLE_DATE settleDate, D.ACCT_NO acctNo, D.ACCT_NAME acctName from SETTLE_TRANS_DATA_TOTAL A LEFT JOIN SETTLE_TRANS_DATA_TOTAL_STATUS B ON A.SEQ_ID = B.SEQ_NO LEFT JOIN STL_SEC_ACCT_INFO C ON A.SEC_ACCT_ID = C.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO D ON D.ACCT_NO = A.ACCT_NO LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = A.FINPROD_ID LEFT JOIN (select T.SEQ_NO, SUM(T.MARCH_QTY) MARCH_QTY,SUM(T.MARCH_AMT) MARCH_AMT from SETTLE_TRANS_DATA_TOTAL_MATCH T GROUP BY T.SEQ_NO) F ON A.SEQ_ID = F.SEQ_NO
AND A.TRADE_MARKET = #{tradeMarket}
AND A.TRADE_PLAT = #{tradePlat}
AND A.PS = #{ps}
AND A.SEC_ACCT_ID = #{secAcctNo}
AND (aa.APPLY_TRADE_ID IN
null) or aa.APPLY_TRADE_ID in (
#{item} )
AND E.FINPROD_MARKET_ID = #{finprodId}
AND A.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
AND A.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND (B.MATCH_STATUS in (#{TRD_MATCH_STATUS_01},#{TRD_MATCH_STATUS_02}) OR B.MATCH_STATUS IS NULL)
AND B.MATCH_STATUS = #{matchStatus}
AND A.FPRICE_AMT >= #{tradeAmt1}
AND A.FPRICE_AMT <= #{tradeAmt2}

SELECT A1.ENTRUST_ID entrustId, D1.TARGET_TYPE targetType, A1.UPDATE_TIME updateTime, #{TRADE_TYPE_02} tradeType, A1.PORTFOLIO_ID portfolioId, B1.PORTFOLIO_NAME portfolioName, CASE WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} THEN #{SEC_TYPE_01} WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} THEN #{SEC_TYPE_06} WHEN A1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06} THEN #{SEC_TYPE_02} WHEN A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) THEN #{SEC_TYPE_09} END secType, CASE WHEN A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) THEN NULL ELSE A1.FINPROD_ID END finprodId, A1.FINPROD_TYPE2 finprodType2, C1.FINPROD_MARKET_ID finprodMarketId, A1.ENTRUST_DATE entrustDate, A1.PS ps, A1.TRADE_MARKET tradeMarket, A1.TRADE_PLAT tradePlat, A1.ENTRUST_AMT entrustAmt, A1.PRICE price, A1.ENTRUST_NUM entrustNum, E1.SEC_ACCT_ID secAcctId, E1.SEC_ACCT_NAME secAcctName, F1.ACCT_NO acctNo, F1.ACCT_NAME acctName FROM ETR_ENTRUST A1 INNER JOIN PTL_PORTFOLIO B1 ON A1.PORTFOLIO_ID = B1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT C1 ON A1.FINPROD_ID = C1.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD D1 ON D1.ENTRUST_ID = A1.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO E1 ON E1.SEC_ACCT_ID = D1.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO F1 ON F1.ACCT_NO = E1.TRD_ACCT_ID WHERE A1.ENTRUST_STATUS = #{ENTRUST_STATUS_03} AND A1.TRADE_MARKET IN (#{TRADE_PLACE_03},#{TRADE_PLACE_04}) AND A1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10})
AND (A1.PORTFOLIO_ID IN
null) or A1.PORTFOLIO_ID in (
#{item} )
AND (A1.FINPROD_TYPE2 IN
null) or A1.FINPROD_TYPE2 in (
#{item} )
AND C1.FINPROD_MARKET_ID = #{finprodId}
AND A1.FINPROD_TYPE2 = #{finprodType1}
AND A1.PS = #{ps}
AND A1.ENTRUST_DATE >= TO_DATE(#{tradeDateBegin}, 'yyyy-mm-dd')
AND A1.ENTRUST_DATE <= TO_DATE(#{tradeDateEnd}, 'yyyy-mm-dd')
AND A1.TRADE_PLAT = #{tradePlat}
AND A1.ENTRUST_DATE = TO_DATE(#{dealDate}, 'yyyy-mm-dd')
AND D1.SEC_ACCT_ID = #{secAccount}

select A.SEQ_NO seqId, A.MATCH_CLASS matchType, A.ENTRUNST_TRADE_ID busiCode, C.TRADE_MARKET tradeMarket, C.APPLY_TRADE_ID applyTradeId, D.PORTFOLIO_ID portfolioId, F.PORTFOLIO_NAME portfolioName, CASE WHEN C.SEC_TYPE = '09' THEN NULL ELSE E.FINPROD_MARKET_ID END finprodMarketId, C.FINPROD_TYPE2 finprodType2, C.SEC_TYPE secType, CASE WHEN C.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ID END finprodId, C.PS ps, A.MARCH_AMT_EN tradeAmt, A.MARCH_QTY_EN tradeNum, C.UNIT_FPRICE tradePrice, C.DEAL_DATE tradeDate, C.CCY ccy from SETTLE_TRANS_DATA_TOTAL_MATCH A INNER JOIN SETTLE_TRANS_DATA_TOTAL_STATUS B ON A.SEQ_NO = B.SEQ_NO AND B.MATCH_STATUS IN (#{TRD_MATCH_STATUS_1},#{TRD_MATCH_STATUS_2}) INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON A.SEQ_NO = C.SEQ_ID LEFT JOIN ETR_ENTRUST D ON D.ENTRUST_ID = A.ENTRUNST_TRADE_ID LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = C.FINPROD_ID LEFT JOIN PTL_PORTFOLIO F ON D.PORTFOLIO_ID = F.PORTFOLIO_ID
AND A.MATCH_CLASS = #{trdMatchType}
AND (C.APPLY_TRADE_ID IN
null) or C.APPLY_TRADE_ID in (
#{item} )
AND C.TRADE_MARKET = #{tradeMarket}
AND D.PORTFOLIO_ID = #{portfolioId}
AND A.ENTRUNST_TRADE_ID = #{busiCode}
AND C.SEC_ACCT_ID = #{secAcctNo}
AND C.PS = #{ps}
AND A.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
AND A.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND E.FINPROD_MARKET_ID = #{finprodId}
AND C.SEC_TYPE = #{secType}
